// frontend/src/components/ConceptBoard.js
import React, { useRef, useState, useEffect } from "react";
import { fetchImages, uploadImage, updateImagePosition, deleteImage, checkServerConnection, updateImageSize } from '../api';

const ConceptBoard = () => {
  const boardRef = useRef(null);
  const fileInputRef = useRef(null);

  const [images, setImages] = useState([]);
  const [draggingId, setDraggingId] = useState(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [transform, setTransform] = useState({ scale: 1, x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });
  const [hoveredImageId, setHoveredImageId] = useState(null);
  const [resizingId, setResizingId] = useState(null);
  const [resizeStart, setResizeStart] = useState({ x: 0, y: 0, width: 0, height: 0 });

  const [showModal, setShowModal] = useState(false);
  const [pendingImage, setPendingImage] = useState(null);
  const [inputName, setInputName] = useState("");
  // CHANGED: From single ID to array of IDs for multiple selections
  const [selectedLoreNoteIds, setSelectedLoreNoteIds] = useState([]);
  const [loreNotes, setLoreNotes] = useState([]); // To store LoreNotes from localStorage for linking

  const [isFullscreen, setIsFullscreen] = useState(false);
  const [errorMessage, setErrorMessage] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [serverOnline, setServerOnline] = useState(false);

  // Categories no longer include 'General' as it will be derived from linked notes or 'Uncategorized'
  const categories = [
    'Characters',
    'World Building', 
    'Music/Audio',
    'Technology',
    'Story/Plot',
    'Antagonists',
    'Environments',
    'Props',
    'Vehicles',
  ];

  const categoryColors = {
    'Characters': '#EC4899',
    'World Building': '#00dbdd', 
    'Music/Audio': '#4ADE80',
    'Technology': '#f59e0b',
    'Story/Plot': '#8b5cf6',
    'Antagonists': '#FF3D3D',
    'Environments': '#10b981',
    'Props': '#f97316',
    'Vehicles': '#6366f1',
    'Uncategorized': '#6b7280' // Added for images without linked notes
  };

  // Check server connection
  useEffect(() => {
    const checkServer = async () => {
      const isOnline = await checkServerConnection();
      setServerOnline(isOnline);
      if (!isOnline) {
        setErrorMessage("Server is offline. Make sure your backend is running on port 5000");
      }
    };
    
    checkServer();
  }, []);

  // Load images from server AND sync to localStorage for LoreNotes integration
  // Also load LoreNotes from localStorage
  useEffect(() => {
    const loadData = async () => {
      if (!serverOnline) return;
      
      setIsLoading(true);
      try {
        const fetchedImages = await fetchImages();
        if (fetchedImages && Array.isArray(fetchedImages)) {
          // Transform images for the board
          const formattedImages = fetchedImages.map(img => ({
            id: img.id.toString(),
            src: `http://localhost:5000${img.url}`,
            x: img.posX || 100,
            y: img.posY || 100,
            name: img.name || img.originalName || 'Untitled',
            // CHANGED: loreNoteIds is now an array
            loreNoteIds: Array.isArray(img.loreNoteIds) ? img.loreNoteIds.map(String) : (img.loreNoteId ? [String(img.loreNoteId)] : []), // Handle existing single loreNoteId or new array
            category: img.category || 'Uncategorized', // Default to Uncategorized
            width: img.width || 300,
            height: img.height || 150
          }));
          setImages(formattedImages);
          
          // IMPORTANT: Store images in localStorage for LoreNotes integration
          localStorage.setItem('conceptBoard_images', JSON.stringify(formattedImages));
        }

        // Load lore notes from localStorage
        const storedLoreNotes = localStorage.getItem('melodicJustice_loreNotes');
        if (storedLoreNotes) {
          setLoreNotes(JSON.parse(storedLoreNotes));
        }

      } catch (error) {
        console.error('Failed to load data:', error);
        setErrorMessage('Failed to load data. Check if server is running on port 5000.');
      } finally {
        setIsLoading(false);
      }
    };

    loadData();

    // Listen for changes in LoreNotes localStorage as well
    const handleLoreNotesStorageChange = (e) => {
      if (e.key === 'melodicJustice_loreNotes') {
        const storedLoreNotes = localStorage.getItem('melodicJustice_loreNotes');
        if (storedLoreNotes) {
          setLoreNotes(JSON.parse(storedLoreNotes));
        }
      }
    };
    window.addEventListener('storage', handleLoreNotesStorageChange);
    return () => window.removeEventListener('storage', handleLoreNotesStorageChange);

  }, [serverOnline]);

  // Also save to localStorage whenever images change
  useEffect(() => {
    if (images.length > 0) { // Only save if there are images
      localStorage.setItem('conceptBoard_images', JSON.stringify(images));
    } else if (images.length === 0) { // If all images are deleted, clear from local storage
      localStorage.removeItem('conceptBoard_images');
    }
  }, [images]);

  // Function to get the effective category of an image
  const getEffectiveImageCategory = (image) => {
    if (image.loreNoteIds && image.loreNoteIds.length > 0 && loreNotes.length > 0) {
      // Find the category of the first linked note, or use 'Uncategorized'
      const linkedNote = loreNotes.find(note => image.loreNoteIds.includes(note.id.toString()));
      return linkedNote ? linkedNote.category : 'Uncategorized';
    }
    return image.category || 'Uncategorized'; // Fallback to image's category or 'Uncategorized'
  };

  // Handle mouse events for dragging images
  const handleMouseDown = (e, id) => {
    e.stopPropagation();
    const image = images.find((img) => img.id === id);
    setDraggingId(id);
    
    // Calculate the mouse position in board coordinates (accounting for transform)
    const boardRect = boardRef.current.getBoundingClientRect();
    const mouseXInBoard = (e.clientX - boardRect.left - transform.x) / transform.scale;
    const mouseYInBoard = (e.clientY - boardRect.top - transform.y) / transform.scale;
    
    // Store the offset between mouse position (in board coordinates) and image position
    setDragOffset({
      x: mouseXInBoard - image.x,
      y: mouseYInBoard - image.y
    });
  };

  const handleMouseMove = (e) => {
    if (draggingId) {
      // Calculate the new mouse position in board coordinates
      const boardRect = boardRef.current.getBoundingClientRect();
      const mouseXInBoard = (e.clientX - boardRect.left - transform.x) / transform.scale;
      const mouseYInBoard = (e.clientY - boardRect.top - transform.y) / transform.scale;
      
      // Set new position based on mouse position minus the initial offset
      setImages((prev) =>
        prev.map((img) =>
          img.id === draggingId
            ? { 
                ...img, 
                x: mouseXInBoard - dragOffset.x, 
                y: mouseYInBoard - dragOffset.y 
              }
            : img
        )
      );
    } else if (resizingId) {
      // Apply similar transformation for resizing
      const boardRect = boardRef.current.getBoundingClientRect();
      const mouseXInBoard = (e.clientX - boardRect.left - transform.x) / transform.scale;
      const mouseYInBoard = (e.clientY - boardRect.top - transform.y) / transform.scale;
      
      const resizeStartXInBoard = (resizeStart.x - boardRect.left - transform.x) / transform.scale;
      const resizeStartYInBoard = (resizeStart.y - boardRect.top - transform.y) / transform.scale;
      
      const deltaX = mouseXInBoard - resizeStartXInBoard;
      const deltaY = mouseYInBoard - resizeStartYInBoard;
      
      // Rest of resize code using deltaX and deltaY
      setImages((prev) => {
        return prev.map((img) => {
          if (img.id !== resizingId) return img;
          
          let newWidth = resizeStart.width;
          let newHeight = resizeStart.height;
          
          switch (resizeStart.direction) {
            case 'se': // Bottom right corner
              newWidth = Math.max(50, resizeStart.width + deltaX);
              newHeight = Math.max(30, resizeStart.height + deltaY);
              break;
            case 'sw': // Bottom left corner
              newWidth = Math.max(50, resizeStart.width - deltaX);
              newHeight = Math.max(30, resizeStart.height + deltaY);
              return { ...img, x: img.x + deltaX, width: newWidth, height: newHeight };
            case 'ne': // Top right corner
              newWidth = Math.max(50, resizeStart.width + deltaX);
              newHeight = Math.max(30, resizeStart.height - deltaY);
              return { ...img, y: img.y + deltaY, width: newWidth, height: newHeight };
            case 'nw': // Top left corner
              newWidth = Math.max(50, resizeStart.width - deltaX);
              newHeight = Math.max(30, resizeStart.height - deltaY);
              return { ...img, x: img.x + deltaX, y: img.y + deltaY, width: newWidth, height: newHeight };
            default:
              break;
          }
          
          return { ...img, width: newWidth, height: newHeight };
        });
      });
    } else if (isPanning) {
      // No change needed for panning
      setTransform((prev) => ({
        ...prev,
        x: prev.x + (e.clientX - panStart.x),
        y: prev.y + (e.clientY - panStart.y),
      }));
      setPanStart({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseUp = async () => {
    if (draggingId && serverOnline) {
      // Update position on the server when dragging ends
      const image = images.find(img => img.id === draggingId);
      if (image) {
        try {
          console.log("Updating position:", image.id, { posX: image.x, posY: image.y });
          await updateImagePosition(image.id, { posX: image.x, posY: image.y });
          console.log("Position updated successfully");
        } catch (error) {
          console.error('Failed to update image position:', error);
          setErrorMessage('Failed to save image position. Server might be offline.');
        }
      }
    }
    
    if (resizingId && serverOnline) {
      // Update size on the server when resizing ends
      const image = images.find(img => img.id === resizingId);
      if (image) {
        try {
          // You'll need to create a new API endpoint for updating size
          await updateImageSize(image.id, { width: image.width, height: image.height });
        } catch (error) {
          console.error('Failed to update image size:', error);
          setErrorMessage('Failed to save image size. Server might be offline.');
        }
      }
    }
    
    setDraggingId(null);
    setResizingId(null);
    setIsPanning(false);
  };

  const handleResizeMouseDown = (e, id, direction) => {
    e.stopPropagation();
    const image = images.find(img => img.id === id);
    setResizingId(id);
    
    // Store absolute client coordinates for consistent calculations
    setResizeStart({
      x: e.clientX, // Store raw screen coordinates
      y: e.clientY,
      width: image.width,
      height: image.height,
      direction: direction
    });
  };

  // Handle wheel events for zooming
  const handleWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY * -0.001;
    const rect = boardRef.current.getBoundingClientRect();
    
    // Get mouse position relative to the board
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    
    setTransform((prev) => {
      const newScale = Math.min(3, Math.max(0.2, prev.scale + delta));
      const scaleDelta = newScale / prev.scale;
      
      // Calculate new position to keep zoom centered on mouse
      const newX = prev.x - (mouseX - prev.x) * (scaleDelta - 1);
      const newY = prev.y - (mouseY - prev.y) * (scaleDelta - 1);
      
      return {
        scale: newScale,
        x: newX,
        y: newY,
      };
    });
  };

  const handleBackgroundMouseDown = (e) => {
    if (e.button === 0) {
      setIsPanning(true);
      setPanStart({ x: e.clientX, y: e.clientY });
    }
  };

  // Handle image upload - now with server integration
  const handleAddImageClick = () => {
    if (!serverOnline) {
      setErrorMessage("Server is offline. Connect to server to upload images.");
      return;
    }
    fileInputRef.current.click();
  };

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    if (!serverOnline) {
      setErrorMessage("Server is offline. Cannot upload image.");
      return;
    }
    
    // Check file size - now we can handle files larger than 1MB!
    if (file.size > 10 * 1024 * 1024) { // 10MB limit (set in server)
      setErrorMessage("Image too large. Please select an image smaller than 10MB.");
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      // Create an image element to get the natural dimensions
      const img = new Image();
      img.onload = () => {
        // Calculate dimensions to maintain aspect ratio
        const maxWidth = 300; // Increased from 250px
        const aspectRatio = img.naturalWidth / img.naturalHeight;
        const width = maxWidth;
        const height = width / aspectRatio;

        setPendingImage({
          file: file, // Store the actual file for upload
          src: reader.result,
          width: width,
          height: height,
          aspectRatio: aspectRatio,
          originalWidth: img.naturalWidth,
          originalHeight: img.naturalHeight
        });
        setInputName(file.name.split('.')[0] || "Untitled");
        // CHANGED: No default category, rely on lore notes or 'Uncategorized'
        // setInputCategory("General"); 
        setSelectedLoreNoteIds([]); // Reset selected lore notes to empty array
        setShowModal(true);
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
    e.target.value = null; // Reset input so same file can be selected again
  };

  const handleAddImageFromModal = async () => {
    if (!pendingImage || !serverOnline) return;
    
    setIsUploading(true);
    setErrorMessage(null);
    
    try {
      let finalCategory = 'Uncategorized'; // Default to Uncategorized if no notes selected
      // If multiple notes are selected, determine the category from the first selected note
      if (selectedLoreNoteIds.length > 0) {
        const firstLinkedNote = loreNotes.find(note => note.id.toString() === selectedLoreNoteIds[0]);
        if (firstLinkedNote) {
          finalCategory = firstLinkedNote.category;
        }
      }

      // Create FormData for file upload
      const formData = new FormData();
      formData.append('file', pendingImage.file);
      formData.append('name', inputName || 'Untitled');
      formData.append('category', finalCategory); // Use finalCategory
      formData.append('posX', '100');
      formData.append('posY', '100');
      formData.append('width', '300');
      formData.append('height', pendingImage.height.toString());
      
      // CHANGED: Append loreNoteIds as a comma-separated string for multi-select
      if (selectedLoreNoteIds.length > 0) {
        formData.append('loreNoteIds', selectedLoreNoteIds.join(',')); 
      }
      
      // Upload to server
      const uploadResult = await uploadImage(formData);
      
      if (uploadResult) {
        // Add the new image to the board
        const newImage = {
          id: uploadResult.id.toString(),
          src: `http://localhost:5000/uploads/${uploadResult.filename}`,
          x: uploadResult.posX || 100,
          y: uploadResult.posY || 100,
          name: uploadResult.name,
          category: uploadResult.category,
          // CHANGED: loreNoteIds from uploadResult will be an array now
          loreNoteIds: Array.isArray(uploadResult.loreNoteIds) ? uploadResult.loreNoteIds.map(String) : [], 
          width: uploadResult.width || 300,
          height: uploadResult.height || 200
        };
        
        setImages(prevImages => [...prevImages, newImage]);
        
        // Close the modal and reset form
        setShowModal(false);
        setInputName("");
        // CHANGED: No default category, reset lore notes selection
        // setInputCategory("General"); 
        setSelectedLoreNoteIds([]); 
        setPendingImage(null);
      }
    } catch (error) {
      console.error('Failed to upload image:', error);
      setErrorMessage(`Failed to upload image: ${error.message}`);
    } finally {
      setIsUploading(false);
    }
  };

  // Function to handle adding/removing lore note IDs for multi-select
  const handleLoreNoteCheckboxChange = (noteId) => {
    setSelectedLoreNoteIds((prevSelected) => {
      if (prevSelected.includes(noteId)) {
        // If already selected, remove it
        return prevSelected.filter((id) => id !== noteId);
      } else {
        // If not selected, add it
        return [...prevSelected, noteId];
      }
    });
  };

  // Function to handle updating an image's loreNoteIds (and potentially category)
  // This needs to be called when editing an *existing* image.
  // Assuming a similar update mechanism will be implemented for existing images.
  const handleUpdateImageDetails = async (imageId, updatedDetails) => {
    if (!serverOnline) {
      setErrorMessage("Server is offline. Cannot update image details.");
      return;
    }
    const currentImage = images.find(img => img.id === imageId);
    if (!currentImage) return;

    // Determine final category and loreNoteIds to send
    let categoryToSend = updatedDetails.category || currentImage.category;
    let loreNoteIdsToSend = updatedDetails.loreNoteIds || currentImage.loreNoteIds;

    // If loreNoteIds are provided, derive category from the first linked note
    if (loreNoteIdsToSend && loreNoteIdsToSend.length > 0) {
      const firstLinkedNote = loreNotes.find(note => loreNoteIdsToSend.includes(note.id.toString()));
      if (firstLinkedNote) {
        categoryToSend = firstLinkedNote.category;
      } else {
        categoryToSend = 'Uncategorized'; // Fallback if linked note not found
      }
    } else {
      categoryToSend = 'Uncategorized'; // If no notes linked, default to Uncategorized
    }

    try {
      // Assuming you have an API endpoint to update image details (category, loreNoteIds, name)
      // This will need to be added to your `api.js` and backend.
      // For now, we simulate and update local state.
      console.log(`Simulating API call: updateImageDetails(${imageId}, { category: ${categoryToSend}, loreNoteIds: ${loreNoteIdsToSend} })`);
      // Replace with actual API call:
      // const updateResult = await updateImageDetails(imageId, { category: categoryToSend, loreNoteIds: loreNoteIdsToSend.join(',') });
      
      setImages(prevImages => prevImages.map(img => 
        img.id === imageId ? { ...img, category: categoryToSend, loreNoteIds: loreNoteIdsToSend } : img 
      ));
      setErrorMessage(null); // Clear any previous error
    } catch (error) {
      console.error('Failed to update image details:', error);
      setErrorMessage('Failed to update image details. Server might be offline or API endpoint missing.');
    }
  };

  // Handle fullscreen toggle
  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      boardRef.current.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable fullscreen: ${err.message}`);
      });
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  // Delete an image
  const handleDeleteImage = async (id) => {
    if (!serverOnline) {
      setErrorMessage("Server is offline. Cannot delete image.");
      return;
    }
    try {
      await deleteImage(id);
      const updatedImages = images.filter(img => img.id !== id);
      setImages(updatedImages);
      // Also clear from localStorage if no images left
      if (updatedImages.length === 0) {
        localStorage.removeItem('conceptBoard_images');
      }
    } catch (error) {
      console.error('Failed to delete image:', error);
      setErrorMessage('Failed to delete image. Server might be offline.');
    }
  };

  // Set up event listeners
  useEffect(() => {
    const board = boardRef.current;
    if (board) {
      board.addEventListener("wheel", handleWheel, { passive: false });
      return () => board.removeEventListener("wheel", handleWheel);
    }
  }, []);

  // Handle fullscreen change event
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  // Close error message after timeout
  useEffect(() => {
    if (errorMessage) {
      const timer = setTimeout(() => {
        setErrorMessage(null);
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [errorMessage]);

  return (
    <div className="rounded-lg p-4 w-full max-w-full" style={{ backgroundColor: '#1a1a1a' }}>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">Concept Board</h2>
          <p className="text-gray-400">Organize and manage concept art and reference images</p>
          {!serverOnline && (
            <p className="text-red-400 text-sm mt-1">⚠️ Server offline - Images stored locally only</p>
          )}
        </div>
        <div className="flex gap-2">
          <button
            onClick={handleAddImageClick}
            className={`px-4 py-2 rounded-lg flex items-center gap-2 ${
              serverOnline ? 'bg-teal-500 text-white hover:bg-teal-600' : 'bg-gray-600 text-gray-300 cursor-not-allowed'
            } transition-all`}
            disabled={!serverOnline}
          >
            <span>+ Add Image</span>
          </button>
          <button
            onClick={toggleFullscreen}
            className="p-2 rounded-lg bg-gray-700 text-white hover:bg-gray-600 transition-all"
          >
            {isFullscreen ? "Exit Fullscreen" : "Fullscreen"}
          </button>
        </div>
      </div>

      {/* Connection status indicator */}
      <div className="mb-4 flex items-center gap-2">
        <div className={`w-3 h-3 rounded-full ${serverOnline ? 'bg-green-500' : 'bg-red-500'}`} />
        <span className="text-white text-sm"> Server {serverOnline ? 'Connected' : 'Disconnected'} </span>
      </div>

      {/* Error message */}
      {errorMessage && (
        <div style={{ backgroundColor: '#f44336', color: 'white', padding: '10px', borderRadius: '5px', marginBottom: '15px' }}>
          {errorMessage}
        </div>
      )}

      <div
        ref={boardRef}
        className="relative w-full h-[600px] bg-gray-800 rounded-lg overflow-hidden border border-gray-700 cursor-grab"
        style={{
          transform: `scale(${transform.scale}) translate(${transform.x}px, ${transform.y}px)`,
          transformOrigin: '0 0',
        }}
        onMouseDown={handleBackgroundMouseDown}
        onMouseUp={handleMouseUp}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseUp} // End drag/pan/resize if mouse leaves board
      >
        {isLoading && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-900 bg-opacity-75 z-20">
            <p className="text-white text-lg">Loading images...</p>
          </div>
        )}

        {images.map((image) => (
          <div
            key={image.id}
            className="absolute group"
            style={{
              left: image.x,
              top: image.y,
              width: image.width,
              height: image.height,
              cursor: draggingId === image.id ? 'grabbing' : 'grab',
              zIndex: draggingId === image.id ? 10 : 1, // Bring dragged image to front
            }}
            onMouseDown={(e) => handleMouseDown(e, image.id)}
            onMouseEnter={() => setHoveredImageId(image.id)}
            onMouseLeave={() => setHoveredImageId(null)}
            onDoubleClick={() => handleDeleteImage(image.id)} // Example: Double click to delete
          >
            <img
              src={image.src}
              alt={image.name}
              className="w-full h-full object-cover rounded-lg shadow-lg"
              style={{
                borderColor: categoryColors[getEffectiveImageCategory(image)] || categoryColors['Uncategorized'],
                borderWidth: '2px',
                borderStyle: 'solid',
              }}
            />
            {/* Image Name */}
            {(hoveredImageId === image.id || draggingId === image.id) && (
              <div className="absolute top-2 left-1/2 -translate-x-1/2 bg-black bg-opacity-75 text-white text-xs px-2 py-1 rounded whitespace-nowrap">
                {image.name}
              </div>
            )}
             {/* Category Tag */}
             {(hoveredImageId === image.id || draggingId === image.id) && (
              <div
                className="absolute bottom-2 left-1/2 -translate-x-1/2 text-white text-xs px-2 py-1 rounded"
                style={{ backgroundColor: categoryColors[getEffectiveImageCategory(image)] || categoryColors['Uncategorized'] }}
              >
                {getEffectiveImageCategory(image)}
              </div>
            )}
            
            {/* Resize handles */}
            {hoveredImageId === image.id && !draggingId && (
              <>
                <div className="resize-handle se" onMouseDown={(e) => handleResizeMouseDown(e, image.id, 'se')} />
                <div className="resize-handle sw" onMouseDown={(e) => handleResizeMouseDown(e, image.id, 'sw')} />
                <div className="resize-handle ne" onMouseDown={(e) => handleResizeMouseDown(e, image.id, 'ne')} />
                <div className="resize-handle nw" onMouseDown={(e) => handleResizeMouseDown(e, image.id, 'nw')} />
              </>
            )}
          </div>
        ))}
      </div>

      {/* Modal for image details (name, category, lore note link) */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50">
          <div className="bg-gray-800 p-6 rounded-lg shadow-xl w-full max-w-md border border-gray-700">
            <h3 className="text-xl font-bold text-white mb-4">Add Image Details</h3>
            
            <div className="mb-4">
              <label htmlFor="imageName" className="block text-gray-300 text-sm font-bold mb-2">
                Image Name
              </label>
              <input
                type="text"
                id="imageName"
                className="shadow appearance-none border border-gray-700 rounded w-full py-2 px-3 bg-gray-700 text-white leading-tight focus:outline-none focus:shadow-outline focus:border-pink-500"
                value={inputName}
                onChange={(e) => setInputName(e.target.value)}
                placeholder="Enter image name"
              />
            </div>
            
            {/* Lore Notes Multi-Select Checkboxes */}
            <div className="mb-4">
              <label className="block text-gray-300 text-sm font-bold mb-2">
                Link to Lore Notes (multiple)
              </label>
              <div className="bg-gray-700 border border-gray-600 rounded p-2 max-h-40 overflow-y-auto lore-scrollbar">
                {loreNotes.length > 0 ? (
                  loreNotes.map((note) => (
                    <div key={note.id} className="flex items-center mb-1">
                      <input
                        type="checkbox"
                        id={`loreNote-${note.id}`}
                        value={note.id.toString()}
                        checked={selectedLoreNoteIds.includes(note.id.toString())}
                        onChange={() => handleLoreNoteCheckboxChange(note.id.toString())}
                        className="form-checkbox h-4 w-4 text-pink-600 transition duration-150 ease-in-out bg-gray-900 border-gray-500 rounded focus:ring-pink-500"
                      />
                      <label htmlFor={`loreNote-${note.id}`} className="ml-2 text-gray-300 text-sm cursor-pointer whitespace-nowrap overflow-hidden text-ellipsis w-full">
                        {note.title} <span className="text-gray-500">({note.category})</span>
                      </label>
                    </div>
                  ))
                ) : (
                  <p className="text-gray-400 text-sm">No Lore Notes available. Create some in Lore Notes tab!</p>
                )}
              </div>
            </div>

            <div style={{ display: "flex", justifyContent: "space-between", marginTop: "10px" }}>
              <button 
                onClick={() => {
                  setShowModal(false);
                  setPendingImage(null);
                  setInputName("");
                  // CHANGED: No default category, reset lore notes selection
                  // setInputCategory("General"); 
                  setSelectedLoreNoteIds([]);
                }} 
                style={{ 
                  padding: "8px 12px", 
                  background: "#444", 
                  color: "#fff", 
                  border: "none", 
                  borderRadius: "4px",
                  cursor: "pointer"
                }}
                disabled={isUploading}
              >
                Cancel
              </button>
              <button 
                onClick={handleAddImageFromModal} 
                style={{ 
                  padding: "8px 16px", 
                  background: isUploading ? "#666" : "#00d1b2", 
                  color: "white", 
                  border: "none", 
                  borderRadius: "4px",
                  cursor: isUploading ? "not-allowed" : "pointer",
                  opacity: isUploading ? 0.7 : 1
                }}
                disabled={isUploading}
              >
                {isUploading ? 'Uploading...' : 'Add Image'}
              </button>
            </div>
          </div>
        </div>
      )} {/* This is the corrected closing for the modal */}
    </div>
  );
};

export default ConceptBoard;
